contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public {
        require(amount > 0);
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        require(amount > balBefore);
        bool reverted;
        try c.transfer(address(0xdead), amount) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.balanceOf(address(this)) == balBefore && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amt) public {
        require(recipient != address(this));
        require(recipient != address(c));

        uint256 beforeBal = c.balanceOf(address(this));
        require(beforeBal >= amt);
        uint256 beforeRecBal = c.balanceOf(recipient);
        uint256 beforeSupply = c.totalSupply();

        bool ok = c.transfer(recipient, amt);

        uint256 afterBal = c.balanceOf(address(this));
        uint256 afterRecBal = c.balanceOf(recipient);
        uint256 afterSupply = c.totalSupply();

        assert(ok && afterBal == beforeBal - amt && afterRecBal == beforeRecBal + amt && afterSupply == beforeSupply);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address owner, address spender, uint256 value, uint256 deadline) public {
        require(deadline < block.timestamp, "must be expired");
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.permit.selector, owner, spender, value, deadline, uint8(1), bytes32(0), bytes32(0)
            )
        );
        require(!ok, "permit with expired deadline must revert");
        assert(c.allowance(owner, spender) == 0 && c.nonces(owner) == 0);
    }
    receive() external payable {}
}

