contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to) public {
        uint256 balBefore = c.balanceOf(to);
        bool reverted;
        uint256 shares;
        try c.buyShares(to) returns (uint256 s, uint256, uint256) {
            reverted = false;
            shares = s;
        } catch {
            reverted = true;
        }
        if (reverted) {
            assert(c.balanceOf(to) == balBefore);
        } else {
            assert(shares > 1000 && c.balanceOf(to) == balBefore + shares);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to) public {
        uint256 balBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        bool ok;
        uint256 s;
        try c.buyShares(to) returns (uint256 shares, uint256, uint256) {
            ok = true;
            s = shares;
        } catch {
            ok = false;
        }
        assert(
            (!ok && c.balanceOf(to) == balBefore && c.totalSupply() == supplyBefore) ||
            (ok && s > 1000 && c.balanceOf(to) == balBefore + s && c.totalSupply() == s + 1001)
        );
    }
    receive() external payable {}
}

